import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"组织架构","description":"","frontmatter":{},"headers":[],"relativePath":"backend/organization.md","filePath":"backend/organization.md","lastUpdated":1794049926000}`),a={name:`backend/organization.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="组织架构" tabindex="-1">组织架构 <a class="header-anchor" href="#组织架构" aria-label="Permalink to “组织架构”">​</a></h1><p>本页说明 Organization 包（Tier 1，依赖 Identity 与 Tenancy）提供的部门、岗位与部门成员，适用于后端开发者。三者都是租户库实体：每个租户一套，平台一侧没有组织架构。</p><h2 id="部门" tabindex="-1">部门 <a class="header-anchor" href="#部门" aria-label="Permalink to “部门”">​</a></h2><table tabindex="0"><thead><tr><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>SysDepartment</code></td><td>编码（租户内唯一，删了可重建）、名称、类型（集团、总部、公司、分公司、事业部、中心、小组等 16 种，缺省部门）、上级、负责人、排序、状态、联系电话、邮箱、地址、说明</td></tr><tr><td><code>SysDepartmentHierarchy</code></td><td>闭包表：每对「祖先—后代」一行（含自身），带深度</td></tr></tbody></table><p>闭包表让「部门及其下级」成为一次索引查询，数据范围的 <code>DepartmentAndChildren</code>、字段安全的部门规则、通知的定向投递都依赖它。</p><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>departments.tree</code></td><td><code>organization.departments.read</code></td><td>部门树（<code>GET</code>，声明只读），带直接成员数，不分页。<code>keyword</code> 不分大小写匹配编码、名称、电话、邮箱、地址与说明，只留命中的部门，上级没命中的当作顶层</td></tr><tr><td><code>departments.get</code></td><td><code>organization.departments.read</code></td><td>详情</td></tr><tr><td><code>departments.create</code></td><td><code>organization.departments.create</code></td><td>创建并挂到上级（为空即顶层）</td></tr><tr><td><code>departments.update</code></td><td><code>organization.departments.update</code></td><td>改名称、类型、负责人、排序、联系方式等，不改上级</td></tr><tr><td><code>departments.move</code></td><td><code>organization.departments.update</code></td><td>移到新上级：整棵子树重算闭包，拒绝移到自己或子孙之下</td></tr><tr><td><code>departments.delete</code></td><td><code>organization.departments.delete</code></td><td>批量；还有子部门或成员的逐项 <code>ORGANIZATION_CONFLICT_002</code>，删除即软删并摘除闭包行</td></tr></tbody></table><p>负责人是本租户的用户（<code>leaderUserId</code>）。前端编辑弹窗按关键字远程检索用户（需要 <code>identity.users.read</code>，看不了用户时这一栏不显示）。</p><h2 id="岗位" tabindex="-1">岗位 <a class="header-anchor" href="#岗位" aria-label="Permalink to “岗位”">​</a></h2><p><code>SysPosition</code>：编码（租户内唯一）、名称、排序、启停、说明。操作 <code>positions.create / get / list / update / delete</code>，权限 <code>organization.positions.*</code>。</p><h2 id="部门成员" tabindex="-1">部门成员 <a class="header-anchor" href="#部门成员" aria-label="Permalink to “部门成员”">​</a></h2><p><code>SysUserDepartment</code>：用户 × 部门（同一用户同一部门一条），带岗位、是否主部门、工号、职级、入职时间（UTC）、部门内排序与备注。</p><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>memberships.list</code></td><td><code>organization.memberships.read</code></td><td>按部门、用户或岗位筛选，可按主部门筛选、按排序 / 创建时间 / 入职时间排序，按数据范围收窄；不支持关键字（用户名在平台库，分库时不能联表）</td></tr><tr><td><code>memberships.create</code></td><td><code>organization.memberships.create</code></td><td>用户须在当前租户（注册在这里或<a href="./multi-tenancy#外部成员">外部成员</a>）；用户的第一个归属自动是主部门，显式设主时其他归属取消主标记</td></tr><tr><td><code>memberships.update</code></td><td><code>organization.memberships.update</code></td><td>改岗位、主部门、工号、职级、入职时间、备注</td></tr><tr><td><code>memberships.delete</code></td><td><code>organization.memberships.delete</code></td><td>批量移出</td></tr></tbody></table><p>加入与移出部门时记领域事件 <code>basicapp.organization.membership-changed</code>（<code>Contracts</code> 的 <code>MembershipChanged</code>：用户、部门、加入还是移出、发生时间），随写入进发件箱；改岗位、主部门等不发。Chat 据此同步部门群成员，见<a href="./chat#部门群同步">在线聊天</a>。</p><p><code>departments.get</code>、<code>departments.tree</code>、<code>positions.get</code>、<code>positions.list</code> 与 <code>memberships.list</code> 同时是 MCP / AI 工具。</p><h2 id="使用方" tabindex="-1">使用方 <a class="header-anchor" href="#使用方" aria-label="Permalink to “使用方”">​</a></h2><table tabindex="0"><thead><tr><th>使用方</th><th>用法</th></tr></thead><tbody><tr><td>Access 数据范围</td><td>本部门 / 本部门及下级 / 自定义部门</td></tr><tr><td>Access 字段安全</td><td>部门目标的规则认所在部门及其上级</td></tr><tr><td>Access 条件属性</td><td><code>subject.departmentcodes</code>、<code>subject.maindepartmentcode</code>、<code>subject.positioncodes</code></td></tr><tr><td>Identity 用户列表</td><td>按部门筛选（含下级），经 <code>Contracts</code> 的 <code>IRecipientSource</code></td></tr><tr><td>Notification</td><td>按部门定向投递（含下级）</td></tr><tr><td>Workflow</td><td>组织类受理人，经下面的组织目录</td></tr></tbody></table><h2 id="组织目录" tabindex="-1">组织目录 <a class="header-anchor" href="#组织目录" aria-label="Permalink to “组织目录”">​</a></h2><p><code>Contracts</code> 的 <code>IOrganizationDirectory</code>（Organization 实现）给别的包按编码取部门成员、部门负责人、岗位任职，按用户取主部门往上的部门链，以及选人用的部门与岗位清单。只读调用所在租户、只取启用的部门与岗位（不含下级部门），平台一侧为空；不做权限与数据范围判定，候选人要不要再与可见的在用账号求交由调用方定。</p><h2 id="演示数据" tabindex="-1">演示数据 <a class="header-anchor" href="#演示数据" aria-label="Permalink to “演示数据”">​</a></h2><p><code>BasicApp:Seed:EnableDemoData</code> 打开时，种子 <code>organization.demo</code> 在演示租户 <code>demo</code> 里写部门 <code>hq → rd / mkt / hr</code>、岗位 <code>gm / manager / engineer / specialist</code> 与负责人，并给演示成员排主部门任职（流程演示要用）：</p><table tabindex="0"><thead><tr><th>账号</th><th>部门 / 岗位</th><th>负责人</th></tr></thead><tbody><tr><td><code>admin</code></td><td>总部 / 总经理</td><td>总部</td></tr><tr><td><code>manager</code></td><td>研发部 / 经理</td><td>研发部</td></tr><tr><td><code>lead</code></td><td>研发部 / 工程师</td><td>—</td></tr><tr><td><code>hr</code></td><td>人事部 / 专员</td><td>—</td></tr></tbody></table><p>只首写：租户里已有部门即跳过。</p><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to “前端”">​</a></h2><p><code>src/modules/organization</code>：部门页是 SchemaPage 树表（关键字搜索、详情抽屉里的成员维护；编辑时改了上级，保存后调 <code>departments.move</code>），岗位页是 SchemaPage 列表。成员列表显示岗位、工号、职级与入职日期（按本地日期显示）。搜索时上级部门的候选与详情里的子部门仍取整棵树。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./data-permission">数据权限与字段安全</a> · <a href="./multi-tenancy">多租户 SaaS</a></li></ul>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};